/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (txa_remk.getValue().length > 200) {
        await $c.win.alert("비고는  200자이하만 입력할 수 있습니다.");
        return false;
    }
    dts_explanation.insertRow();
    dts_explanation.setCellData(1, "EXPLDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
    dts_explanation.setCellData(1, "EXPLDISCLS_ORD_NO", scwin.gExplDisclsOrdNo);
    dts_explanation.setCellData(1, "REG_ID", js_emp_no);
    dts_explanation.setCellData(1, "REMK", txa_remk.getValue());

    // alert(dts_nfaith.text);

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_explanation_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_explanation_info",
            action : "/ExplanationDisclosure.do",
            ref : "dts_explanation",
            target : "trs_explanation_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

// 답변연결 삭제(담당자가 수동으로 연결한것)

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (scwin.gInputTp === 'A') {
        await $c.win.alert("상장법인이 제출한 해명공시는 삭제하실 수 없습니다.");
        // edt_deadline_dd.focus();
        return;
    }
    const rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_explanation.insertRow();
        dts_explanation.setCellData(1, "EXPLDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
        dts_explanation.setCellData(1, "EXPLDISCLS_ORD_NO", scwin.gExplDisclsOrdNo);
        trs_explanation_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_explanation_info",
            action : "/ExplanationDisclosure.do",
            ref : "dts_explanation",
            target : "trs_explanation_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    // self.close();
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.update();
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function() {
    await scwin.delete();
};

/**
 * @method
 * @name dts_explanation_info_OnLoadError
 * @description dts_explanation_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_explanation_info_OnLoadError = async function() {
    await $c.win.alert(dts_explanation_info);
};

/**
 * @method
 * @name dts_explanation_info_OnLoadCompleted
 * @description dts_explanation_info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_explanation_info_OnLoadCompleted = function(rowcount) {
    const vProcsEmpNo = dts_explanation_info.getCellData(1, "REG_ID");
    if (vProcsEmpNo === 'SYSTEM_Y' || vProcsEmpNo === 'SYSTEM_N') {
        scwin.gInputTp = 'A'; // 상장법인이 제출한 경우
        btn_Delete.hide();
    } else {
        scwin.gInputTp = 'M'; // 신규 등록한 경우
        btn_Delete.show("");
    }
};

/**
 * @method
 * @name trs_explanation_info_OnSuccess
 * @description explanation info On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_explanation_info_OnSuccess = async function() {
    await $c.win.alert("성공적으로 처리 되었습니다.");
    // self.close();
    await $c.win.closePopup();
    // 부모창 reload 처리해야함
    $c.frame.path("../").fn_reload();
};

/**
 * @method
 * @name trs_explanation_info_OnFail
 * @description explanation info On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_explanation_info_OnFail = async function() {
    await $c.win.alert('trs_explanation_info.OnFail() :' + trs_explanation_info.ErrorMsg);
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.resizeToWin();
    fn_GetParentValue();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_explanation_info",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_explanation_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 가우스헤더 셋팅
    const sbmOptions2 = {
        id : "sbm_dts_explanation",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_explanation=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //  정보 읽어오기
    fn_ReadInfo();
};
